def main():
    entries=json.loads((ROOT/'out/shop_catalog/inventory.json').read_text(encoding='utf-8'))['entries'][73:89]
    jobs=[]
    for e,(title,brief) in zip(entries,SPECS):
        j=dict(e)
        j.update(title_fr=title,output=f'{e["number"]}_{e["id"]}_sheet.png',design_brief=brief,status='catalogue')
        j['refs']=[str(ROOT/'out/shop_catalog'/e['front']),str(ART/'01_counter_sheet_v2.png')]
        j['submitted_prompt']=BASE+brief+f' Exact title: "{e["number"]} — {title.upper()}".'
        jobs.append(j)
    (ART/'items_74_89_prompts.json').write_text(json.dumps({'tool':'built-in image_gen','mode':'generation from catalogue and approved style references','date':'2026-10-27','jobs':jobs},ensure_ascii=False,indent=2),encoding='utf-8')
    print('Prepared16 remaining original catalogue sheets74–89.')

if __name__=='__main__':main()
